const TOP_LEVEL_FILTERS: [&str; 6] = [
    "annexB",
    "built-ins",
    "harness",
    "intl402",
    "language",
    "staging",
];
const MATRIX_SPLIT_FILTERS: [&str; 4] = ["built-ins", "intl402", "language", "staging"];
const SNAPSHOT_VERSION: u32 = 5;
/// Snapshot version 4 predates per-failure outcome data. Read-only status,
/// triage, backlog, and comparison paths may still consume such snapshots
/// because every outcome can be *derived* from the recorded failure kind and
/// detail with the same classifier used at write time — nothing is invented.
/// Resume/merge paths stay strict: new results are never merged into a legacy
/// snapshot.
const LEGACY_SNAPSHOT_VERSION: u32 = 4;
const MATRIX_STRATEGY_VERSION: u32 = 2;
// Keep matrix nodes small enough that slow semantic buckets like RegExp and
// Temporal checkpoint incrementally instead of monopolizing a whole run.
const MATRIX_RECURSION_THRESHOLD: usize = 500;
const MATRIX_CHUNK_SIZE: usize = 250;
// Checkpoint periodically so an interrupted first run or low-RAM resume never
// restarts a whole slow node, without paying the O(n)
// summarize/sort/fs::write cost after every single case (which made resume
// runs O(n^2) in the number of completed cases). A final checkpoint is always
// written after a resume run completes, so normal resume exits never lose
// progress; only an interrupt can lose up to
// `RESUME_CASE_CHECKPOINT_INTERVAL - 1` already-completed cases.
const RESUME_CASE_CHECKPOINT_INTERVAL: usize = 10;
/// Matches the stack required by Porffor's Wasm-AOT current-thread execution
/// entry. Test262 workers persist for many cases, so this avoids a nested
/// worker spawn for each compile, emit, and execution phase.
const TEST262_WORKER_STACK_SIZE: usize = 64 * 1024 * 1024;
// Wasmtime epoch interruption applies the configured timeout only after a
// Wasm-AOT module starts executing. An isolated child still needs a separate
// finite allowance for parsing, lowering, emission, and cold native compile.
const WASM_AOT_CHILD_COMPILE_ALLOWANCE_MS: u64 = 300_000;
const DISABLE_CASE_RUNNER_ENV: &str = "PORFFOR_TEST262_DISABLE_CASE_RUNNER";
const WASM_AOT_INACTIVE_REALM_GLOBAL: &str = "  global: undefined,";
const WASM_AOT_ACTIVE_REALM_GLOBAL: &str = "  global: globalThis,";
const WASM_AOT_INACTIVE_CREATE_REALM: &str =
    "  createRealm: function () {\n    __porfUnsupportedHost('createRealm');\n  },";
const WASM_AOT_ACTIVE_CREATE_REALM: &str =
    "  createRealm: function () {\n    return __porfCreateRealm();\n  },";
const WASM_AOT_AGENT_TIMER_PRELUDE: &str = r#"function setTimeout(callback, delay) {
  Promise.resolve().then(function () {
    $262.agent.sleep(delay);
    callback();
  });
}
"#;
static TEST262_PANIC_HOOK: Once = Once::new();

#[derive(Debug)]
struct CapturingTest262Output {
    lines: Arc<Mutex<Vec<String>>>,
}

impl HostHooks for CapturingTest262Output {
    fn print_line(&self, text: &str) {
        self.lines
            .lock()
            .expect("Test262 output capture lock should not be poisoned")
            .push(text.to_string());
    }
}

